-- This guarded migration only runs once; admin deletions stay deleted.
CREATE TABLE IF NOT EXISTS schema_migrations (
  version VARCHAR(120) PRIMARY KEY,
  applied_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM schema_migrations WHERE version = '003_add_freshwater_species') THEN
    INSERT INTO fish (id, data, sort_order)
    VALUES
  ('boesemani-rainbowfish', '{"id":"boesemani-rainbowfish","name":"Cá cầu vồng Boesemani","scientificName":"Melanotaenia boesemani","description":"Màu xanh cam · Bơi khỏe theo đàn","group":"tropical","level":"medium","category":"NƯỚC NGỌT · CÁ CẦU VỒNG","difficulty":"Cần bể rộng","summary":"Có thể dài khoảng 10–12cm khi trưởng thành","tank":"Từ 120L cho đàn nhỏ; cần chiều dài bể và khoảng bơi thoáng","temperature":"22–27°C (mốc tham khảo cho cá cầu vồng)","ph":"6.5–8.0 (mốc tham khảo cho cá cầu vồng)","groupSize":"Cá sống theo đàn; nên nuôi từ 5 con. Chừa khoảng bơi mở và dòng nước vừa phải.","food":"Ăn tạp; dùng thức ăn flakes/viên chất lượng, bổ sung thức ăn đông lạnh hoặc sống cỡ nhỏ.","compatibility":"Thường phù hợp với cá cộng đồng có kích thước và mức hoạt động tương tự. Tránh ghép với cá quá nhỏ hoặc quá nhút nhát.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Melanotaenia_boesemani.jpg?width=1200","imageCredit":"Atamari · CC BY-SA 3.0 · Wikimedia Commons","imageSource":"https://commons.wikimedia.org/wiki/File:Melanotaenia_boesemani.jpg","sources":[{"label":"OATA — chăm sóc cá cầu vồng (thông số nhóm)","url":"https://ornamentalfish.org/what-we-do/advice-information/care-sheets/caresheets-tropical-freshwater-fish/how-to-look-after-rainbowfish/"},{"label":"FishBase — Melanotaenia boesemani","url":"https://www.fishbase.se/summary/Melanotaenia-boesemani.html"}]}'::jsonb, (SELECT COALESCE(MAX(sort_order), -1) + 1 FROM fish)),
  ('cardinal-tetra', '{"id":"cardinal-tetra","name":"Cá cardinal tetra (neon vua)","scientificName":"Paracheirodon axelrodi","description":"Sọc xanh đỏ nổi bật · Cá bơi theo đàn","group":"tropical","level":"easy","category":"NƯỚC NGỌT · TETRA","difficulty":"Dễ bắt đầu","summary":"Cá nhỏ, thường dài khoảng 3–5cm","tank":"Từ 45L cho một đàn nhỏ; bể đã ổn định và có khoảng bơi","temperature":"22–27°C (mốc tham khảo cho tetra nuôi sinh sản nhân tạo)","ph":"6.5–8.0 (mốc tham khảo cho tetra nuôi sinh sản nhân tạo)","groupSize":"Cá theo đàn; nuôi ít nhất 5 con, đàn lớn hơn thường giúp cá bớt căng thẳng.","food":"Thức ăn flakes/viên nhỏ; có thể bổ sung thức ăn sống hoặc đông lạnh cỡ nhỏ. Chỉ cho lượng cá ăn hết trong vài phút.","compatibility":"Ghép với cá hiền, kích thước tương đương; không nuôi cùng cá lớn có thể ăn chúng.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cardinal_tetras.jpg?width=1200","imageCredit":"Artūrs Grebstelis · CC BY 2.0 · Wikimedia Commons","imageSource":"https://commons.wikimedia.org/wiki/File:Cardinal_tetras.jpg","sources":[{"label":"OATA — chăm sóc tetra và pencilfish (thông số nhóm)","url":"https://ornamentalfish.org/what-we-do/advice-information/care-sheets/caresheets-tropical-freshwater-fish/how-to-look-after-tetras-and-pencilfish/"},{"label":"FishBase — Paracheirodon axelrodi","url":"https://www.fishbase.se/summary/Paracheirodon-axelrodi.html"}]}'::jsonb, (SELECT COALESCE(MAX(sort_order), -1) + 2 FROM fish)),
  ('ember-tetra', '{"id":"ember-tetra","name":"Cá tetra lửa","scientificName":"Hyphessobrycon amandae","description":"Nhỏ nhắn · Sắc cam ấm áp","group":"tropical","level":"easy","category":"NƯỚC NGỌT · TETRA","difficulty":"Dễ bắt đầu","summary":"Loài tetra nhỏ, thường dài khoảng 2cm","tank":"Từ 45L cho đàn nhỏ theo hướng dẫn chung của OATA","temperature":"22–27°C (mốc tham khảo cho tetra nuôi sinh sản nhân tạo)","ph":"6.5–8.0 (mốc tham khảo cho tetra nuôi sinh sản nhân tạo)","groupSize":"Cá theo đàn; nuôi ít nhất 5 con. Có thể dùng cây thủy sinh làm chỗ trú nhưng vẫn cần khoảng bơi.","food":"Thức ăn flakes/viên rất nhỏ; bổ sung thức ăn đông lạnh hoặc sống cỡ nhỏ khi phù hợp.","compatibility":"Chọn cá hiền và nhỏ tương tự; tránh bạn bể lớn có thể xem tetra lửa là mồi.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Funkensalmler_Feuertetra_oder_Feuersalmler_Hyphessobrycon_amandae.JPG?width=1200","imageCredit":"Usien · CC BY 3.0 · Wikimedia Commons","imageSource":"https://commons.wikimedia.org/wiki/File:Funkensalmler_Feuertetra_oder_Feuersalmler_Hyphessobrycon_amandae.JPG","sources":[{"label":"OATA — chăm sóc tetra và pencilfish (thông số nhóm)","url":"https://ornamentalfish.org/what-we-do/advice-information/care-sheets/caresheets-tropical-freshwater-fish/how-to-look-after-tetras-and-pencilfish/"},{"label":"FishBase — Hyphessobrycon amandae","url":"https://www.fishbase.se/summary/Hyphessobrycon-amandae.html"}]}'::jsonb, (SELECT COALESCE(MAX(sort_order), -1) + 3 FROM fish)),
  ('rummy-nose-tetra', '{"id":"rummy-nose-tetra","name":"Cá tetra mũi đỏ","scientificName":"Petitella bleheri","description":"Đầu đỏ · Đuôi sọc đen trắng","group":"tropical","level":"medium","category":"NƯỚC NGỌT · TETRA","difficulty":"Cần bể ổn định","summary":"Cá tetra nhỏ, thường dài khoảng 4–5cm","tank":"Từ 45L cho đàn nhỏ; ưu tiên bể trưởng thành và chất lượng nước ổn định","temperature":"22–27°C (mốc tham khảo cho tetra nuôi sinh sản nhân tạo)","ph":"6.5–8.0 (mốc tham khảo cho tetra nuôi sinh sản nhân tạo)","groupSize":"Cá theo đàn; nuôi ít nhất 5 con, đàn lớn hơn và bể ổn định giúp giảm căng thẳng.","food":"Thức ăn flakes/viên nhỏ; bổ sung thức ăn đông lạnh hoặc sống cỡ nhỏ, tránh cho ăn dư.","compatibility":"Ghép với cá hiền có kích thước tương đương. Tránh cá lớn săn mồi hoặc loài hay rỉa vây.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Brilliant_rummy_nose_-_Petitella_bleheri_-_2.jpg?width=1200","imageCredit":"Lerdsuwa · CC BY-SA 3.0 · Wikimedia Commons","imageSource":"https://commons.wikimedia.org/wiki/File:Brilliant_rummy_nose_-_Petitella_bleheri_-_2.jpg","sources":[{"label":"OATA — chăm sóc tetra và pencilfish (thông số nhóm)","url":"https://ornamentalfish.org/what-we-do/advice-information/care-sheets/caresheets-tropical-freshwater-fish/how-to-look-after-tetras-and-pencilfish/"},{"label":"FishBase — Petitella bleheri","url":"https://www.fishbase.se/summary/Petitella-bleheri.html"}]}'::jsonb, (SELECT COALESCE(MAX(sort_order), -1) + 4 FROM fish))
    ON CONFLICT (id) DO NOTHING;

    UPDATE fish SET data = data || '{"image":"https://images.pexels.com/photos/2564494/pexels-photo-2564494.jpeg?auto=compress&cs=tinysrgb&w=1200","imageCredit":"Stacey Koenitz · Pexels","imageSource":"https://www.pexels.com/photo/betta-fish-inside-an-aquarium-2564494/"}'::jsonb, updated_at = NOW()
    WHERE id = 'betta' AND data->>'image' = 'https://images.pexels.com/photos/2564494/pexels-photo-2564494.jpeg?auto=compress&cs=tinysrgb&w=1200';
    UPDATE fish SET data = data || '{"image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cobra_Guppy_(Poecilia_reticulata).JPG?width=1200","imageCredit":"Andrew Sheedy · CC BY-SA 4.0 · Wikimedia Commons","imageSource":"https://commons.wikimedia.org/wiki/File:Cobra_Guppy_(Poecilia_reticulata).JPG"}'::jsonb, updated_at = NOW()
    WHERE id = 'guppy' AND data->>'image' = 'https://images.pexels.com/photos/36426327/pexels-photo-36426327.jpeg?auto=compress&cs=tinysrgb&w=1200';
    UPDATE fish SET data = data || '{"image":"https://commons.wikimedia.org/wiki/Special:FilePath/Paracheirodon_innesi_neon_tetra.jpg?width=1200","imageCredit":"SOK · CC BY-SA 4.0 · Wikimedia Commons","imageSource":"https://commons.wikimedia.org/wiki/File:Paracheirodon_innesi_neon_tetra.jpg"}'::jsonb, updated_at = NOW()
    WHERE id = 'neon' AND data->>'image' = 'https://images.unsplash.com/photo-1535591273668-578e31182c4f?auto=format&fit=crop&w=900&q=85';
    UPDATE fish SET data = data || '{"image":"https://commons.wikimedia.org/wiki/Special:FilePath/Xiphophorus_maculatus_Platy.JPG?width=1200","imageCredit":"Usien · CC BY-SA 4.0 · Wikimedia Commons","imageSource":"https://commons.wikimedia.org/wiki/File:Xiphophorus_maculatus_Platy.JPG"}'::jsonb, updated_at = NOW()
    WHERE id = 'platy' AND data->>'image' = 'https://images.unsplash.com/photo-1544551763-46a013bb70d5?auto=format&fit=crop&w=900&q=85';
    UPDATE fish SET data = data || '{"image":"https://commons.wikimedia.org/wiki/Special:FilePath/Carassiusauratus.jpg?width=1200","imageCredit":"Kateryna Martyniuk · CC BY 4.0 · Wikimedia Commons","imageSource":"https://commons.wikimedia.org/wiki/File:Carassiusauratus.jpg"}'::jsonb, updated_at = NOW()
    WHERE id = 'goldfish' AND data->>'image' = 'https://images.unsplash.com/photo-1522069169874-c58ec4b76be5?auto=format&fit=crop&w=900&q=85';
    UPDATE fish SET data = data || '{"image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pterophyllum_Scalare.jpg?width=1200","imageCredit":"Sarbast.T.Hameed · CC BY-SA 4.0 · Wikimedia Commons","imageSource":"https://commons.wikimedia.org/wiki/File:Pterophyllum_Scalare.jpg"}'::jsonb, updated_at = NOW()
    WHERE id = 'angelfish' AND data->>'image' = 'https://images.unsplash.com/photo-1546026423-cc4642628d2b?auto=format&fit=crop&w=900&q=85';
    INSERT INTO schema_migrations (version) VALUES ('003_add_freshwater_species');
  END IF;
END $$;
